window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-73ce02e4f16d25e1"]={"versions": [{"id": "FIG-73ce02e4f16d25e1", "releases": ["R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Architektur- und Metamodell-Mapping-Diagramm der AUTOSAR Adaptive Platform. Das Diagramm illustriert die Zuordnung eines anwendungsspezifischen PortPrototypes einer Software-Komponente zu einem modellierten Diagnose-Event (<code>DiagnosticEvent</code>) des Diagnostic Managers über Service-Oriented Architecture (SOA)-Konstrukte und Manifest-Deklarationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Hauptblöcke und übergeordnete Metamodell-Entitäten:</p>\n<ul class=\"fig-list\"><li><strong>Application Software Component</strong>: Beinhaltet ein <code>DiagnosticEventNeeds</code> (mit Aggregations- bzw. Kompositionsraute angebunden an <code>SwcServiceDependency</code>), die <code>SwcServiceDependency</code> selbst sowie eine <code>RoleBasedPortAssignment</code> mit dem Attribut <code>role: DiagnosticMonitor</code>. Über eine gerichtete Assoziation ist die <code>RoleBasedPortAssignment</code> an einen <code>R</code>-Port (Required Port) der Komponente angebunden.\n</li><li><strong>Diagnostic Manager</strong>: Beinhaltet einen <code>P</code>-Port (Provided Port) und ein Zielobjekt <code>DiagnosticEvent</code>.\n</li><li><strong>ServiceInterface</strong>: Modelliert als Schnittstellendefinition unterhalb der Komponenten mit <code>shortName: DiagnosticMonitor</code> und der Methode <code>method: SetEventStatus</code>. Beide Ports (<code>R</code> und <code>P</code>) referenzieren dieses <code>ServiceInterface</code> über gestrichelte Verbindungslinien.\n</li><li><strong>DiagnosticEventPortMapping</strong>: Übergeordnetes Mapping-Element, das über gestrichelte Pfeile auf die <code>SwcServiceDependency</code> der Anwendungskomponente sowie das <code>DiagnosticEvent</code> des Diagnostic Managers verweist. Der <code>P</code>-Port des Diagnostic Managers verweist ebenfalls mit einer gestrichelten Linie auf das <code>DiagnosticEvent</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt primär eine statische Konfigurations- und Modellierungszuordnung im Manifest. Das Zusammenspiel beschreibt:</p>\n<ol class=\"fig-list\"><li>Deklaration des Dienstbedarfs (<code>DiagnosticEventNeeds</code>) in der <code>Application Software Component</code> über <code>SwcServiceDependency</code>.\n</li><li>Zuweisung des spezifischen Required Ports (<code>R</code>) über <code>RoleBasedPortAssignment</code> (<code>role: DiagnosticMonitor</code>).\n</li><li>Port-Typisierung über das gemeinsame <code>ServiceInterface</code> (<code>DiagnosticMonitor</code>), wobei die Software-Komponente als Client die Methode <code>SetEventStatus</code> am Provided Port (<code>P</code>) des <code>Diagnostic Manager</code> konsumiert.\n</li><li>Explizite Manifest-Abbildung über <code>DiagnosticEventPortMapping</code>, welche die <code>SwcServiceDependency</code> der SWC mit dem konkreten <code>DiagnosticEvent</code> des Diagnostic Managers verknüpft.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen für die Diagnose-Ereignismeldung im Manifest ein <code>DiagnosticEventPortMapping</code> konfigurieren, das die Komponentenabhängigkeit mit dem <code>DiagnosticEvent</code> synchronisiert. Der Kommunikationspfad ist serviceorientiert über einen <code>R</code>-Port der Software-Komponente und einen <code>P</code>-Port des Diagnostic Managers definiert, typisiert gegen das Service-Interface <code>DiagnosticMonitor</code> mit der Methode <code>SetEventStatus</code>.</p>"}, {"id": "FIG-70ec366a1e221487", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Architektur- und Metamodell-Mapping-Diagramm der AUTOSAR Adaptive Platform. Das Diagramm illustriert die Zuordnung eines anwendungsspezifischen PortPrototypes einer Software-Komponente zu einem modellierten Diagnose-Event (<code>DiagnosticEvent</code>) des Diagnostic Managers über Service-Oriented Architecture (SOA)-Konstrukte und Manifest-Deklarationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Hauptblöcke und übergeordnete Metamodell-Entitäten:</p>\n<ul class=\"fig-list\"><li><strong>Application Software Component</strong>: Beinhaltet ein <code>DiagnosticEventNeeds</code> (mit Aggregations- bzw. Kompositionsraute angebunden an <code>SwcServiceDependency</code>), die <code>SwcServiceDependency</code> selbst sowie eine <code>RoleBasedPortAssignment</code> mit dem Attribut <code>role: DiagnosticMonitor</code>. Über eine gerichtete Assoziation ist die <code>RoleBasedPortAssignment</code> an einen <code>R</code>-Port (Required Port) der Komponente angebunden.\n</li><li><strong>Diagnostic Manager</strong>: Beinhaltet einen <code>P</code>-Port (Provided Port) und ein Zielobjekt <code>DiagnosticEvent</code>.\n</li><li><strong>ServiceInterface</strong>: Modelliert als Schnittstellendefinition unterhalb der Komponenten mit <code>shortName: DiagnosticMonitor</code> und der Methode <code>method: SetEventStatus</code>. Beide Ports (<code>R</code> und <code>P</code>) referenzieren dieses <code>ServiceInterface</code> über gestrichelte Verbindungslinien.\n</li><li><strong>DiagnosticEventPortMapping</strong>: Übergeordnetes Mapping-Element, das über gestrichelte Pfeile auf die <code>SwcServiceDependency</code> der Anwendungskomponente sowie das <code>DiagnosticEvent</code> des Diagnostic Managers verweist. Der <code>P</code>-Port des Diagnostic Managers verweist ebenfalls mit einer gestrichelten Linie auf das <code>DiagnosticEvent</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt primär eine statische Konfigurations- und Modellierungszuordnung im Manifest. Das Zusammenspiel beschreibt:</p>\n<ol class=\"fig-list\"><li>Deklaration des Dienstbedarfs (<code>DiagnosticEventNeeds</code>) in der <code>Application Software Component</code> über <code>SwcServiceDependency</code>.\n</li><li>Zuweisung des spezifischen Required Ports (<code>R</code>) über <code>RoleBasedPortAssignment</code> (<code>role: DiagnosticMonitor</code>).\n</li><li>Port-Typisierung über das gemeinsame <code>ServiceInterface</code> (<code>DiagnosticMonitor</code>), wobei die Software-Komponente als Client die Methode <code>SetEventStatus</code> am Provided Port (<code>P</code>) des <code>Diagnostic Manager</code> konsumiert.\n</li><li>Explizite Manifest-Abbildung über <code>DiagnosticEventPortMapping</code>, welche die <code>SwcServiceDependency</code> der SWC mit dem konkreten <code>DiagnosticEvent</code> des Diagnostic Managers verknüpft.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen für die Diagnose-Ereignismeldung im Manifest ein <code>DiagnosticEventPortMapping</code> konfigurieren, das die Komponentenabhängigkeit mit dem <code>DiagnosticEvent</code> synchronisiert. Der Kommunikationspfad ist serviceorientiert über einen <code>R</code>-Port der Software-Komponente und einen <code>P</code>-Port des Diagnostic Managers definiert, typisiert gegen das Service-Interface <code>DiagnosticMonitor</code> mit der Methode <code>SetEventStatus</code>.</p>"}, {"id": "FIG-bb50812bbe6515a3", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Architektur- und Metamodell-Mapping-Diagramm der AUTOSAR Adaptive Platform. Das Diagramm illustriert die Zuordnung eines anwendungsspezifischen PortPrototypes einer Software-Komponente zu einem modellierten Diagnose-Event (<code>DiagnosticEvent</code>) des Diagnostic Managers über ereignisbasierte Service-Oriented Architecture (SOA)-Konstrukte und Manifest-Deklarationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Hauptblöcke und übergeordnete Metamodell-Entitäten:</p>\n<ul class=\"fig-list\"><li><strong>Application Software Component</strong>: Beinhaltet ein <code>DiagnosticEventNeeds</code> (mit Raute angebunden an <code>SwcServiceDependency</code>), die <code>SwcServiceDependency</code> sowie eine <code>RoleBasedPortAssignment</code> mit dem Attribut <code>role: DiagnosticMonitor</code>. Über eine gerichtete Assoziation ist die <code>RoleBasedPortAssignment</code> an einen <code>P</code>-Port (Provided Port) der Komponente angebunden.\n</li><li><strong>Diagnostic Manager</strong>: Beinhaltet einen <code>R</code>-Port (Required Port) und ein Zielobjekt <code>DiagnosticEvent</code>.\n</li><li><strong>ServiceInterface</strong>: Modelliert als Schnittstellendefinition unterhalb der Komponenten mit <code>shortName: DiagnosticMonitor</code> und dem Ereigniselement <code>event: MonitorAction</code>. Beide Ports (<code>P</code> und <code>R</code>) referenzieren dieses <code>ServiceInterface</code> über gestrichelte Verbindungslinien.\n</li><li><strong>DiagnosticEventPortMapping</strong>: Übergeordnetes Mapping-Element, das über gestrichelte Pfeile auf die <code>SwcServiceDependency</code> der Anwendungskomponente sowie das <code>DiagnosticEvent</code> des Diagnostic Managers verweist. Der <code>R</code>-Port des Diagnostic Managers verweist ebenfalls mit einer gestrichelten Linie auf das <code>DiagnosticEvent</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine ereignisbasierte Zuordnungskonfiguration dar:</p>\n<ol class=\"fig-list\"><li>Deklaration des Dienstbedarfs (<code>DiagnosticEventNeeds</code>) in der <code>Application Software Component</code> über <code>SwcServiceDependency</code>.\n</li><li>Zuweisung des spezifischen Provided Ports (<code>P</code>) über <code>RoleBasedPortAssignment</code> (<code>role: DiagnosticMonitor</code>).\n</li><li>Port-Typisierung über das gemeinsame <code>ServiceInterface</code> (<code>DiagnosticMonitor</code>), wobei die Software-Komponente als Provider das Event <code>MonitorAction</code> für den Required Port (<code>R</code>) des <code>Diagnostic Manager</code> bereitstellt.\n</li><li>Explizite Manifest-Abbildung über <code>DiagnosticEventPortMapping</code>, welche die <code>SwcServiceDependency</code> der SWC mit dem konkreten <code>DiagnosticEvent</code> des Diagnostic Managers verknüpft.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen für die Diagnose-Ereignismeldung im Manifest ein <code>DiagnosticEventPortMapping</code> konfigurieren, das die Komponentenabhängigkeit mit dem <code>DiagnosticEvent</code> synchronisiert. Der Kommunikationspfad ist ereignisorientiert aufgebaut: Die Software-Komponente stellt über einen <code>P</code>-Port das Event <code>MonitorAction</code> gemäß ServiceInterface <code>DiagnosticMonitor</code> bereit, welches vom <code>Diagnostic Manager</code> über dessen <code>R</code>-Port konsumiert wird.</p>"}, {"id": "FIG-7228f90a4aaa0c5b", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Architektur- und Metamodell-Mapping-Diagramm der AUTOSAR Adaptive Platform zur Anbindung von Diagnose-Datenbezeichnern. Das Diagramm zeigt die Zuordnung eines PortPrototypes einer Software-Komponente zu einem <code>DiagnosticDataIdentifier</code> des Diagnostic Managers über einen Inter-Process-Communication-Kanal (<code>IPC Channel</code>) und Manifest-Mapping-Deskriptoren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm besteht aus folgenden Blöcken und Elementen:</p>\n<ul class=\"fig-list\"><li><strong>Application Software Component</strong>: Beinhaltet <code>DiagnosticValueNeeds</code> (mit Raute angebunden an <code>SwcServiceDependency</code>), die <code>SwcServiceDependency</code> sowie eine <code>RoleBasedPortAssignment</code> mit dem Attribut <code>role = DiagnosticService-DataIdentifierPortMapping</code>. Die <code>RoleBasedPortAssignment</code> verweist gerichtet auf einen <code>P</code>-Port (Provided Port) der Komponente.\n</li><li><strong>Diagnostic Manager</strong>: Beinhaltet einen <code>R</code>-Port (Required Port) und das Zielobjekt <code>DiagnosticDataIdentifier</code>.\n</li><li><strong>IPC Channel</strong>: Vermittelndes Verbindungselement zwischen dem <code>P</code>-Port der Application Software Component und dem <code>R</code>-Port des Diagnostic Managers, dargestellt über gestrichelte Verbindungslinien.\n</li><li><strong>DiagnosticServiceDataIdentifierPortMapping</strong>: Übergeordnetes Mapping-Element, das über gestrichelte Pfeile auf die <code>SwcServiceDependency</code> der Anwendungskomponente sowie den <code>DiagnosticDataIdentifier</code> des Diagnostic Managers verweist. Der <code>R</code>-Port des Diagnostic Managers ist ebenfalls über eine gestrichelte Linie an <code>DiagnosticDataIdentifier</code> angebunden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt die Datenanbindung für Diagnose-Identifier:</p>\n<ol class=\"fig-list\"><li>Deklaration des Wertebedarfs (<code>DiagnosticValueNeeds</code>) an der <code>SwcServiceDependency</code>.\n</li><li>Port-Zuweisung des Provided Ports (<code>P</code>) über <code>RoleBasedPortAssignment</code> mit der Rolle <code>DiagnosticService-DataIdentifierPortMapping</code>.\n</li><li>Kommunikation zwischen dem Bereitsteller-Port (<code>P</code>) der SWC und dem Konsumenten-Port (<code>R</code>) des Diagnostic Managers über einen dedizierten <code>IPC Channel</code>.\n</li><li>Metamodell-Verknüpfung über <code>DiagnosticServiceDataIdentifierPortMapping</code>, welches die Abhängigkeit der Anwendungskomponente auf den <code>DiagnosticDataIdentifier</code> im Diagnostic Manager abbildet.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Zur Bereitstellung von Diagnose-Identifikatordaten ist im Manifest ein <code>DiagnosticServiceDataIdentifierPortMapping</code> zu definieren, das <code>SwcServiceDependency</code> mit <code>DiagnosticDataIdentifier</code> verknüpft. Die Software-Komponente agiert über ihren <code>P</code>-Port als Datenquelle mit der Rolle <code>DiagnosticService-DataIdentifierPortMapping</code>, während der Diagnostic Manager die Daten über seinen <code>R</code>-Port empfängt. Als Übertragungsmechanismus ist ein <code>IPC Channel</code> vorgesehen.</p>"}, {"id": "FIG-3432158e9d6dc2f6", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Architektur- und Metamodell-Mapping-Diagramm der AUTOSAR Adaptive Platform zur Anbindung von Diagnose-Datenbezeichnern. Das Diagramm zeigt die Zuordnung eines PortPrototypes einer Software-Komponente zu einem <code>DiagnosticDataIdentifier</code> des Diagnostic Managers über einen Inter-Process-Communication-Kanal (<code>IPC Channel</code>) und Manifest-Mapping-Deskriptoren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm besteht aus folgenden Blöcken und Elementen:</p>\n<ul class=\"fig-list\"><li><strong>Application Software Component</strong>: Beinhaltet <code>DiagnosticValueNeeds</code> (mit Raute angebunden an <code>SwcServiceDependency</code>), die <code>SwcServiceDependency</code> sowie eine <code>RoleBasedPortAssignment</code> mit dem Attribut <code>role = DiagnosticService-DataIdentifierPortMapping</code>. Die <code>RoleBasedPortAssignment</code> verweist gerichtet auf einen <code>P</code>-Port (Provided Port) der Komponente.\n</li><li><strong>Diagnostic Manager</strong>: Beinhaltet einen <code>R</code>-Port (Required Port) und das Zielobjekt <code>DiagnosticDataIdentifier</code>.\n</li><li><strong>IPC Channel</strong>: Vermittelndes Verbindungselement zwischen dem <code>P</code>-Port der Application Software Component und dem <code>R</code>-Port des Diagnostic Managers, dargestellt über gestrichelte Verbindungslinien.\n</li><li><strong>DiagnosticServiceDataIdentifierPortMapping</strong>: Übergeordnetes Mapping-Element, das über gestrichelte Pfeile auf die <code>SwcServiceDependency</code> der Anwendungskomponente sowie den <code>DiagnosticDataIdentifier</code> des Diagnostic Managers verweist. Der <code>R</code>-Port des Diagnostic Managers ist ebenfalls über eine gestrichelte Linie an <code>DiagnosticDataIdentifier</code> angebunden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt die Datenanbindung für Diagnose-Identifier:</p>\n<ol class=\"fig-list\"><li>Deklaration des Wertebedarfs (<code>DiagnosticValueNeeds</code>) an der <code>SwcServiceDependency</code>.\n</li><li>Port-Zuweisung des Provided Ports (<code>P</code>) über <code>RoleBasedPortAssignment</code> mit der Rolle <code>DiagnosticService-DataIdentifierPortMapping</code>.\n</li><li>Kommunikation zwischen dem Bereitsteller-Port (<code>P</code>) der SWC und dem Konsumenten-Port (<code>R</code>) des Diagnostic Managers über einen dedizierten <code>IPC Channel</code>.\n</li><li>Metamodell-Verknüpfung über <code>DiagnosticServiceDataIdentifierPortMapping</code>, welches die Abhängigkeit der Anwendungskomponente auf den <code>DiagnosticDataIdentifier</code> im Diagnostic Manager abbildet.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Zur Bereitstellung von Diagnose-Identifikatordaten ist im Manifest ein <code>DiagnosticServiceDataIdentifierPortMapping</code> zu definieren, das <code>SwcServiceDependency</code> mit <code>DiagnosticDataIdentifier</code> verknüpft. Die Software-Komponente agiert über ihren <code>P</code>-Port als Datenquelle mit der Rolle <code>DiagnosticService-DataIdentifierPortMapping</code>, während der Diagnostic Manager die Daten über seinen <code>R</code>-Port empfängt. Als Übertragungsmechanismus ist ein <code>IPC Channel</code> vorgesehen.</p>"}], "trans": [{"from": "FIG-73ce02e4f16d25e1", "to": "FIG-70ec366a1e221487", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-70ec366a1e221487", "to": "FIG-bb50812bbe6515a3", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Port-Typen vertauscht: Der Port an <code>Application Software Component</code> wechselt von R-Port zu P-Port; der Port an <code>Diagnostic Manager</code> wechselt von P-Port zu R-Port.\n</li><li>Schnittstellen-Signatur geändert: Innerhalb von <code>ServiceInterface</code> wird das Methodenelement <code>method: SetEventStatus</code> durch das Eventelement <code>event: MonitorAction</code> ersetzt.\n</li></ul>"}, {"from": "FIG-bb50812bbe6515a3", "to": "FIG-7228f90a4aaa0c5b", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Zuordnungsklasse geändert: <code>DiagnosticEventPortMapping</code> wird durch <code>DiagnosticServiceDataIdentifierPortMapping</code> ersetzt.\n</li><li>Diagnostisches Element im <code>Diagnostic Manager</code> geändert: <code>DiagnosticEvent</code> wird durch <code>DiagnosticDataIdentifier</code> ersetzt.\n</li><li>Service-Bedarf geändert: <code>DiagnosticEventNeeds</code> wird durch <code>DiagnosticValueNeeds</code> ersetzt.\n</li><li>Port-Rolle geändert: In <code>RoleBasedPortAssignment</code> wechselt der Wert von <code>role: DiagnosticMonitor</code> zu <code>role = DiagnosticService-DataIdentifierPortMapping</code>.\n</li><li>Schnittstellenverbindung ersetzt: Das UML-Element <code>ServiceInterface</code> (mit Name <code>DiagnosticMonitor</code> und Element <code>MonitorAction</code>) entfällt; die Kommunikation zwischen dem P-Port der SWC und dem R-Port des Diagnostic Managers erfolgt nun über einen <code>IPC Channel</code>.\n</li></ul>"}, {"from": "FIG-7228f90a4aaa0c5b", "to": "FIG-3432158e9d6dc2f6", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
